create extension if not exists pgcrypto;
create table public.users (id uuid primary key references auth.users(id) on delete cascade,email text not null,name text,created_at timestamptz not null default now());
create table public.businesses (id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),name text not null,legal_name text,logo_url text,country text not null default 'ES',currency text not null default 'EUR',stripe_account_id text,subscription_status text not null default 'trialing',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.employees (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,photo_url text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.locations (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,type text not null default 'table',public_token text not null unique,active boolean not null default true,created_at timestamptz not null default now());
create table public.tips (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),employee_id uuid references public.employees(id),location_id uuid not null references public.locations(id),amount numeric(10,2) not null check(amount>0),currency text not null,status text not null check(status in ('pending','paid','failed','refunded')),stripe_payment_intent_id text unique,stripe_checkout_session_id text unique,created_at timestamptz not null default now());
create table public.tip_settings (id uuid primary key default gen_random_uuid(),business_id uuid unique not null references public.businesses(id) on delete cascade,suggested_amount_1 numeric(10,2) not null default 1,suggested_amount_2 numeric(10,2) not null default 2,suggested_amount_3 numeric(10,2) not null default 3,allow_custom_amount boolean not null default true,minimum_amount numeric(10,2) not null default .5,maximum_amount numeric(10,2) not null default 100,show_employee_photos boolean not null default true,tip_distribution_mode text not null default 'employee' check(tip_distribution_mode in ('employee','team','custom')));
create table public.subscriptions (id uuid primary key default gen_random_uuid(),business_id uuid unique not null references public.businesses(id) on delete cascade,stripe_customer_id text,stripe_subscription_id text,plan text not null,status text not null,current_period_end timestamptz);
create index tips_business_created_idx on public.tips(business_id,created_at desc);create index employees_business_idx on public.employees(business_id);create index locations_business_idx on public.locations(business_id);
alter table public.businesses enable row level security; alter table public.employees enable row level security; alter table public.locations enable row level security; alter table public.tips enable row level security; alter table public.tip_settings enable row level security; alter table public.subscriptions enable row level security;
create policy "owners manage businesses" on public.businesses for all using (owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "owners manage employees" on public.employees for all using (exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid())) with check(exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid()));
create policy "owners manage locations" on public.locations for all using (exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid())) with check(exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid()));
create policy "owners view tips" on public.tips for select using (exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid()));
create policy "owners manage settings" on public.tip_settings for all using (exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid())) with check(exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid()));
create policy "owners view subscriptions" on public.subscriptions for select using (exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid()));
